<?php
require_once __DIR__.'/../includes/admin_layout.php';$orders=readJson(__DIR__.'/../data/orders.json');$menu=readJson(__DIR__.'/../data/menu.json');$sales=0;$completed=0;$cancelled=0;$qty=0;$productSales=[];foreach($orders as $o){$st=$o['status']??'';if($st==='completed')$completed++;if($st==='cancelled')$cancelled++;if($st!=='cancelled')$sales+=(float)($o['total']??0);foreach($o['items']??[] as $it){$q=(int)($it['quantity']??0);$qty+=$q;$productSales[$it['name']??'Unknown']=($productSales[$it['name']??'Unknown']??0)+$q;}}arsort($productSales);adminStart('Reports & Analytics','reports');?><section class="stat-grid"><div class="admin-stat"><span>💰</span><div><small>Net Sales</small><strong>₹<?=number_format($sales,2)?></strong></div></div><div class="admin-stat"><span>🛒</span><div><small>Items Sold</small><strong><?=$qty?></strong></div></div><div class="admin-stat"><span>✅</span><div><small>Completed</small><strong><?=$completed?></strong></div></div><div class="admin-stat"><span>❌</span><div><small>Cancelled</small><strong><?=$cancelled?></strong></div></div></section><div class="admin-panels"><section class="admin-panel"><h2>🏆 Best Selling Products</h2><div class="table-wrap"><table><tr><th>Product</th><th>Units Sold</th></tr><?php foreach(array_slice($productSales,0,10,true) as $name=>$q):?><tr><td><?=h($name)?></td><td><?=h($q)?></td></tr><?php endforeach;?></table></div></section><section class="admin-panel"><h2>📋 Product Catalog</h2><p>Total products: <b><?=count($menu)?></b></p><p>Available: <b><?=count(array_filter($menu,fn($p)=>!empty($p['available'])))?></b></p><p>Sold out: <b><?=count(array_filter($menu,fn($p)=>empty($p['available'])))?></b></p></section></div><?php adminEnd();?>